(async()=>{const c=new OffscreenCanvas(2,2),g=c.getContext('webgl'),e=g.getExtension('WEBGL_lose_context');if(!e)return null;const events=[];c.addEventListener('webglcontextlost',ev=>{events.push([ev.type,ev.cancelable]);ev.preventDefault()});c.addEventListener('webglcontextrestored',ev=>events.push([ev.type,ev.cancelable]));const b=g.createBuffer();g.bindBuffer(g.ARRAY_BUFFER,b);g.bufferData(g.ARRAY_BUFFER,8,g.STATIC_DRAW);g.clearColor(1,0,0,1);e.loseContext();const out={now:g.isContextLost(),errors:[g.getError(),g.getError()],attributes:g.getContextAttributes(),extensions:g.getSupportedExtensions(),create:Object.prototype.toString.call(g.createBuffer()),old:g.isBuffer(b)};await new Promise(r=>setTimeout(r,20));out.events=events.slice();out.createLater=Object.prototype.toString.call(g.createBuffer());e.restoreContext();await new Promise(r=>setTimeout(r,60));out.restored=g.isContextLost();out.finalEvents=events;out.same=e===g.getExtension('WEBGL_lose_context');out.oldAfter=g.isBuffer(b);out.color=Array.from(g.getParameter(g.COLOR_CLEAR_VALUE));out.binding=g.getParameter(g.ARRAY_BUFFER_BINDING);return out})()